section.script:
var s = document.URL.split('#');
if(s.length > 1) {
  // console.log('got anchor: |' + s[1] + '|');
  var element = document.getElementById(s[1]);
  if(element) {
      element.classList.add('targeted');
  } else {
    // console.log('Cannot find element with id |' + s[1] + '|');
  }
}
